<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Messaging</h1><p>Private institute conversations with participant access control.</p></div></header><section class="module-card"><div class="module-card__body"><form method="post" action="<?= url('/admin/communication/messaging') ?>"><?= csrf_field() ?><div class="module-form-grid"><div class="module-field"><label>Recipient</label><select class="module-select" name="recipient_id" required><?php foreach($recipients as$r):?><option value="<?= $r['id'] ?>"><?= e($r['name'].' — '.$r['email']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Subject</label><input class="module-input" name="subject"></div><div class="module-field field--wide"><label>Message</label><textarea class="module-textarea" name="message" required></textarea></div></div><button class="btn btn--primary">New Chat</button></form></div></section><section class="module-card chat-layout"><aside class="chat-list"><header class="chat-list__header"><h2>Chats</h2></header><?php foreach($conversations as$c):?><a href="<?= url('/admin/communication/messaging?conversation='.$c['id']) ?>" class="module-card__body"><strong><?= e($c['participant_name']?:$c['subject']?:'Conversation') ?></strong><?php if($c['unread_count']):?> <span class="status-badge"><?= (int)$c['unread_count'] ?> new</span><?php endif ?><br><small><?= e($c['updated_at']) ?></small></a><?php endforeach ?><?php if(!$conversations):?><div class="compact-empty"><h3>No Conversations</h3></div><?php endif ?></aside><div class="module-card__body"><?php if($activeConversation):?><div class="chat-history"><?php foreach($activeConversation['messages']as$m):?><article class="notice-panel"><strong><?= e($m['sender_name']) ?></strong><p><?= nl2br(e($m['body'])) ?></p><small><?= e($m['created_at']) ?></small></article><?php endforeach ?></div><form method="post" action="<?= url('/admin/communication/messaging/'.$activeConversation['id']) ?>"><?= csrf_field() ?><textarea class="module-textarea" name="message" required></textarea><button class="btn btn--primary">Send Message</button></form><?php else:?><div class="compact-empty"><h3>Select a conversation</h3></div><?php endif ?></div></section></div></div></main>
